"""Writes docs/research/rubric_evaluator.md from reports/ai/rubric-eval-frozen-<split>.json, reports/ai/rubric-latency.json and tools/bench/rubric_frozen.json: `tools/.venv/Scripts/python.exe tools/bench/rubric_report.py`. Every number on the page comes from those files."""
from __future__ import annotations

import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
R = ROOT / "reports" / "ai"
SYS = {"baseline_gate_as_served": "Baseline gate (unchanged)", "rubric_credit_only": "Rubric evaluator, its own credit conditions", "rubric_credit_plus_production_guards": "Rubric evaluator + production cue and assertion checks",
       "rubric_AND_baseline_gate": "Rubric evaluator AND baseline gate (both must credit the same act)"}


def fmt(f: dict) -> str:
    return "; ".join(f"{x['objective']} {x['verdict']} ({x['modality']}, {x['reason']})" for x in f) or "nothing reported"


def render() -> str:
    D = {s: json.loads((R / f"rubric-eval-frozen-{s}.json").read_text(encoding="utf-8")) for s in ("dev", "test", "test2")}
    lat = json.loads((R / "rubric-latency.json").read_text(encoding="utf-8"))
    fz = json.loads((ROOT / "tools" / "bench" / "rubric_frozen.json").read_text(encoding="utf-8"))
    L = ["# Context-conditioned semantic rubric evaluation (Qwen3.5 4B) against the current gate", "",
         "_Generated by `tools/bench/rubric_report.py`; do not edit by hand. EXPLORATORY: `tests/action_bench_v1` is synthetic, written by one author family, labelled by construction; it is not independent evidence of generalisation. "
         "Dev is where the prompt was chosen (163-row subset); test and test2 were scored once each with the frozen prompt. test was already used to write the production assertion check (ADR-0020), so both baseline numbers on it are development-contaminated; test2 is the less contaminated of the two. No human labels exist (EX-01, EX-18)._", "",
         "## What was built", "",
         f"* One local model call per utterance (`{fz['model']}`, digest `{lat['model']['digest'][:12]}`, matches `content/assessment/thresholds.json`: {lat['model']['digest_matches_content_assessment_thresholds_json']}; Ollama {lat['model']['ollama_version']}, llama.cpp runner, thinking OFF, temperature 0, seed 7, at most {fz['max_findings']} findings, {fz['options']['num_predict']} output tokens). "
         "All 19 objectives (the approved acts of `taxonomy.json`, their definitions verbatim) are eligible at every call because the benchmark rows carry no scenario state; `rubric_eval.eligible(step)` also reads the behaviour windows of `mapping.json` but kept out-of-window objectives eligible, which is NOT the engine's rule (`EvidenceStore.Submit` rejects them as CONTEXT_MISMATCH; corrected 19 Oct 2026, ADR-0022); the frozen results used all objectives and are unaffected.",
         "* Result schema per finding: objective, verdict (SUPPORTED / NOT_SUPPORTED / UNCERTAIN), actor, modality, evidence, reason code. Omitted objectives count as NOT_SUPPORTED. Evidence must be a verbatim part of the utterance; a defective finding is recorded and dropped, never repaired.",
         "* Interpretation and credit are separate (`rubric_eval.evaluate` / `credit`). A critical objective is never credited from speech. The production gate was not modified: the baseline is its recorded decisions, and the production critical-cue and non-assertive checks are called unchanged where stated.", "",
         "* **Baseline reconciliation (checked, not assumed).** The gate was re-run unchanged on all three splits (`tools/bench/nli_baseline.py`). On test2 it reproduces the committed `reports/ai/act-benchmark-test2.json` exactly (72 credited, 69/140 legitimate, 0/40 critical, 0/300 non-assertive). "
         "On test the committed `act-benchmark.json` still records the gate BEFORE the assertion check was widened (92 credited, 70 legitimate, 22/300 non-assertive credited); the gate as it stands now credits 70 (66/140 legitimate, 0/300), because the widening was written from that split's failures (ADR-0020). The test baseline here is therefore the current gate, optimised on test.",
         "## Prompt selection (dev subset only)", ""] + [f"* **{k}**: {v}" for k, v in fz["selection_log_dev_subset_163_rows"].items()] + ["", f"Caveat: {fz['caveat']}", "",
         "## Objective-level interpretation (19 objectives x 488 sentences = 9,272 decisions per split)", "",
         "A decision is correct if the evaluator's SUPPORTED (trainee, actual, evidence verified) matches the labelled act of an `actual` row; the benchmark labels one act per sentence, so a second SUPPORTED objective on such a row is counted as a false positive (strict; the arguable cases are in the JSON).", "",
         "| Split | TP | FP | FN | Precision | Recall | F1 | Macro-F1 (objectives with support) |", "|---|---|---|---|---|---|---|---|"]
    for s, d in D.items():
        o = d["objective_level"]
        L.append(f"| {s}{' (prompt chosen here)' if s == 'dev' else ''} | {o['tp']} | {o['fp']} | {o['fn']} | {o['precision']} | {o['recall']} | {o['f1']} | {o['macro_f1_over_objectives_with_support']} |")
    L += ["", "Label view on the 188 core rows (the evaluator's first SUPPORTED objective, else NONE; the baseline's head), same rows and truth as the NLI report:", "", "| Split | Rubric accuracy | Rubric macro-F1 | Baseline accuracy | Baseline macro-F1 |", "|---|---|---|---|---|"]
    for s, d in D.items():
        a, b = d["label_view_core"]["rubric_first_supported_else_NONE"], d["label_view_core"]["baseline_head"]
        L.append(f"| {s} | {a['accuracy']} | {a['macro_f1']} | {b['accuracy']} | {b['macro_f1']} |")
    L += ["", "Per-objective precision, recall and F1 and both confusion matrices: `reports/ai/rubric-eval-frozen-<split>.json`.", "", "## Credit decisions (140 legitimate, 300 adversarial and 40 critical rows per split)", "",
          "| Split | System | Critical credited | Adversarial credited | Legitimate recall | Credited precision |", "|---|---|---|---|---|---|"]
    for s, d in D.items():
        for k, v in d["credit"].items():
            L.append(f"| {s} | {SYS[k]} | {v['critical_false_credit']} | {v['adversarial_false_credit']} | {v['legitimate_credit_recall']} | {v['credited_precision']} |")
    L += ["", "## Interpretation errors by category (frozen prompt, counts over the stated rows)", "", "| Split | Category | Rows | Correct act supported | No objective supported | Wrong: the denied/intended/imagined/reported/other-speaker act supported | Critical content read as an ordinary act | UNCERTAIN |", "|---|---|---|---|---|---|---|---|"]
    for s, d in D.items():
        for c, v in d["by_category"].items():
            L.append(f"| {s} | {c} | {v['n']} | {v.get('named_act_supported', '-')} | {v.get('no_objective_supported', '-')} | {v.get('named_act_supported (WRONG)', '-') if 'named_act_supported (WRONG)' in v or c in ('negation', 'intention', 'hypothetical', 'reported', 'actor_change', 'incomplete') else '-'} | {v.get('critical_content_supported_under_an_ordinary_objective', 0)} | {v.get('has_uncertain', 0)} |")
    L += ["", "Abstention coverage (rows with an UNCERTAIN finding or a failed/defective call, so no usable decision): " + ", ".join(f"{s} {d['abstention_coverage']['rows_without_usable_decision']}/{d['abstention_coverage']['of']}" for s, d in D.items()) + ".",
          "Call health: " + "; ".join(f"{s}: {d['call_health']['calls']} calls, transport errors {sum(d['call_health']['transport_errors'].values())}, not JSON {d['call_health']['not_json_or_schema']}, cut at the token cap {d['call_health']['truncated_at_token_cap']}, thinking text {d['call_health']['thinking_present']}, rows with a finding defect {d['call_health']['rows_with_any_defect']}" for s, d in D.items()) + ".", "",
          "## Failure examples (test2)", ""]
    ex = D["test2"]["examples"]
    for k, title in (("model_critical_under_ordinary", "Critical content read as an ordinary act (a semantic error that only the guards or the engine can catch)"), ("model_wrong_adversarial_supported", "A non-performed act read as performed"),
                     ("model_wrong_legit_not_supported", "A legitimate act missed or read as another act"), ("gate_wrong_credit", "Credit decision wrong (rubric + production guards)")):
        L += [f"**{title}** ({D['test2']['example_counts'][k]} in test2; first {len(ex[k])}):", ""]
        L += [f"* \"{e['text']}\" - truth {e['truth']} ({e['status']}, {e['category']}); evaluator: {fmt(e['findings'])}" + (f"; credited as {e['credited_as']}" if 'credited_as' in e else "") for e in ex[k]] + [""]
    w, c, b = lat["warm"], lat["cold_start"]["first_call"], lat["budget"]
    L += ["## Latency and resources (this desktop: GTX 1660 SUPER 6 GB, Ryzen 5 2600, 16 GB; nothing else on the GPU)", "",
          "| Measure | Value |", "|---|---|",
          f"| Warm, whole call, frozen prompt, 24 probe calls | median {w['wall_ms']['median']} ms, p95 {w['wall_ms']['p95']} ms, max {w['wall_ms']['max']} ms |",
          f"| Warm, whole call, benchmark runs (487 calls each) | median {D['test']['latency_ms']['wall']['median']} / {D['test2']['latency_ms']['wall']['median']} ms, p95 {D['test']['latency_ms']['wall']['p95']} / {D['test2']['latency_ms']['wall']['p95']} ms, max {D['test']['latency_ms']['wall']['max']} / {D['test2']['latency_ms']['wall']['max']} ms (test / test2) |",
          f"| Where it goes | prompt evaluation {w['prompt_eval_ms']['median']} ms ({w['prompt_tokens']} prompt tokens, about {w['prompt_tokens_per_s']} tokens/s, evaluated again on every call: {w['evaluator_vs_a_second_identical_call']}), generation {w['generation_ms']['median']} ms median / {w['generation_ms']['p95']} ms p95 ({w['output_tokens']['median']} output tokens median, {w['generation_tokens_per_s']} tokens/s) |",
          f"| Cold start (model unloaded, then one call) | {c['wall_ms']} ms ({c['load_ms']} ms loading the model) |",
          f"| Memory | {lat['gpu_loaded']['memory_used_mb']} MB of {lat['gpu_loaded']['memory_total_mb']} MB video memory in use with the model resident (model 3.1 GB, `ollama ps` 100% GPU); model-runner process {lat['runner_rss'][0]['rss_mb']} MB resident |",
          f"| Application-side parse, validation and credit decision | {lat['application_side_ms_per_utterance']} ms per utterance |",
          f"| Baseline gate (embedding call included) | median {b['baseline_gate_ms']['median']} ms, p95 {b['baseline_gate_ms']['p95']} ms |",
          f"| Patient reply (40-token proxy) alone / when issued 300 ms after an evaluator call | median {lat['contention']['patient_reply_alone_ms']['median']} ms / {lat['contention']['patient_reply_issued_300ms_after_an_evaluator_call_ms']['median']} ms (p95 {lat['contention']['patient_reply_issued_300ms_after_an_evaluator_call_ms']['p95']} ms): one model slot, the reply waits |", "",
          f"**Thinking.** The Ollama `think: false` option is supported for this model and behaves as claimed: {lat['thinking']['think_false']['calls']} calls returned no thinking text ({lat['thinking']['think_false']['thinking_chars']} characters) and only the JSON tokens ({lat['thinking']['think_false']['output_tokens']}). With the option omitted (or true) the model thinks by default: all {lat['thinking']['think_omitted']['calls']} calls spent the whole {fz['options']['num_predict']}-token cap on thinking and returned EMPTY content (done_reason length). Every benchmark call used `think: false`; none carried thinking text.", "",
          f"**Budget.** The documented target is a p95 voice round trip under {b['round_trip_target_p95_s']} s (feature C31) and a 3 s timeout for a live model call (`unity_ai_hooks.md`). Recognition takes {b['asr_seconds_per_clip']['p95']} s at p95 and the first spoken sentence {b['speech_output_first_sentence_s']['p95_worst']} s (both read from the committed reports, not re-measured), which leaves {b['left_for_everything_between_s']} s for everything between them. "
          f"The evaluator adds {b['evaluator_added_if_serial_s']['median']} s median and {b['evaluator_added_if_serial_s']['p95']} s p95 if it runs in the reply path: it does not fit (serial_in_the_reply_path_fits = {b['serial_in_the_reply_path_fits']}), and it exceeds the 3 s live-call timeout on its own. Run beside the reply, it still queues in front of the patient's reply on the single model slot (ADR-0011). "
          "Speech recognition was not re-measured here, and no Unity-side time exists (no headset run).", ""]
    return "\n".join(L) + "\n"


def main() -> int:
    out = ROOT / "docs" / "research" / "rubric_evaluator.md"
    out.write_text(render(), encoding="utf-8", newline="\n")
    print("wrote", out.relative_to(ROOT).as_posix())
    return 0


if __name__ == "__main__":
    sys.exit(main())
